 resize(options={}){const w=innerWidth,h=innerHeight,dpr=Math.min(2,(globalThis.devicePixelRatio||1)*(.75+(options.sharpness??100)/200)),pixel=options.pixelScale||1;if(w!==this.width||h!==this.height||this.dpr!==dpr||this.pixel!==pixel){this.width=w;this.height=h;this.dpr=dpr;this.pixel=pixel;this.canvas.width=Math.round(w*dpr);this.canvas.height=Math.round(h*dpr);this.fx.width=Math.ceil(w*dpr/pixel);this.fx.height=Math.ceil(h*dpr/pixel);}this.ctx.imageSmoothingEnabled=false;this.fc.imageSmoothingEnabled=false;this.scale=Math.max(.65,Math.min(1.2,Math.min(w,h)/660))/(1+(options.vision||0));this.intensity=options.fxIntensity??.75;this.shake=0;if(this.celebration&&!this.motion.matches&&['boss','hurt'].includes(this.celebration.type)){const age=(performance.now()-this.celebration.start)/1000;this.shake=Math.max(0,1-age/.3)*Math.sin(age*120)*7*(options.screenShake??.35);}}
 tile(map,variant){const key=map+variant;if(this.tiles.has(key))return this.tiles.get(key);const tile=document.createElement('canvas');tile.width=tile.height=32;const c=tile.getContext('2d'),p=PALETTES[map]||PALETTES.village;c.fillStyle=p[0];c.fillRect(0,0,32,32);
  if(map==='quarry'||map==='mill'||map==='village'&&variant<3)for(let y=0;y<32;y+=8)for(let x=-8;x<32;x+=16){const xx=x+(y%16?8:0);c.fillStyle=p[1];c.fillRect(xx+1,y+1,14,6);c.fillStyle=p[2];c.fillRect(xx+2,y+1,11,1);c.fillStyle=p[3];c.fillRect(xx+1,y+7,14,1);if(hash(x+variant,y)>.55){c.fillStyle=p[0];c.fillRect(xx+8,y+3,1,3);c.fillRect(xx+9,y+5,2,1);}}
  for(let i=0;i<14;i++){const x=Math.floor(hash(i+variant*7,2)*30),y=Math.floor(hash(variant,i+3)*30);c.fillStyle=i%4===0?p[2]:p[1];c.fillRect(x,y,2+i%2,1);if(i%3===0){c.fillStyle=p[3];c.fillRect(x+1,y-2,1,3);c.fillStyle=p[2];c.fillRect(x,y-1,1,2);}}if(variant===4){c.fillStyle=p[4];for(let i=0;i<3;i++)c.fillRect(6+i*3,18-i%2*2,1,1);}this.tiles.set(key,tile);return tile;}
 shadow(x,y,w){const c=this.ctx;c.fillStyle='#0a111c70';c.fillRect(Math.round(x-w/2),Math.round(y-3),w,6);c.fillRect(Math.round(x-w/2+4),Math.round(y-5),w-8,10);}
